/* ---- freestanding string helpers ---- */

static size_t sdu_strlen(const char *s) {
    size_t len = 0;
    while (s[len]) len++;
    return len;
}

static void sdu_memcpy(char *dst, const char *src, size_t n) {
    size_t i;
    for (i = 0; i < n; i++) dst[i] = src[i];
}

static const char *sdu_strstr(const char *haystack, const char *needle) {
    size_t nlen;
    if (!*needle) return haystack;
    nlen = sdu_strlen(needle);
    while (*haystack) {
        size_t i;
        bool match = true;
        for (i = 0; i < nlen; i++) {
            if (haystack[i] != needle[i]) { match = false; break; }
        }
        if (match) return haystack;
        haystack++;
    }
    return (const char *)0;
}

/* ---- buffer writer ---- */

typedef struct {
    char *buf;
    size_t cap;
    size_t pos;
    bool overflow;
} SduWriter;

static void sdu_wr_init(SduWriter *w, char *buf, size_t cap) {
    w->buf = buf;
    w->cap = cap;
    w->pos = 0;
    w->overflow = false;
}

static void sdu_wr_str(SduWriter *w, const char *s) {
    size_t len = sdu_strlen(s);
    if (w->pos + len < w->cap) {
        sdu_memcpy(w->buf + w->pos, s, len);
        w->pos += len;
        w->buf[w->pos] = '\0';
    } else {
        w->overflow = true;
    }
}

static void sdu_wr_char(SduWriter *w, char c) {
    if (w->pos + 1 < w->cap) {
        w->buf[w->pos++] = c;
        w->buf[w->pos] = '\0';
    } else {
        w->overflow = true;
    }
}

static void sdu_wr_int(SduWriter *w, int n) {
    char tmp[12];
    int i = 0;
    int neg = 0;
    if (n < 0) { neg = 1; n = -n; }
    if (n == 0) { tmp[i++] = '0'; }
    else { while (n > 0) { tmp[i++] = (char)('0' + n % 10); n /= 10; } }
    if (neg) sdu_wr_char(w, '-');
    while (i > 0) sdu_wr_char(w, tmp[--i]);
}

static const char *sdu_itoa(int n) {
    static char buf[12];
    SduWriter w;
    sdu_wr_init(&w, buf, sizeof(buf));
    sdu_wr_int(&w, n);
    return buf;
}

/* ---- replace first occurrence ---- */

static void sdu_replace_first(SduWriter *w, const char *tmpl, const char *marker, const char *replacement) {
    const char *pos = sdu_strstr(tmpl, marker);
    if (!pos) {
        sdu_wr_str(w, tmpl);
        return;
    }
    while (tmpl < pos) { sdu_wr_char(w, *tmpl); tmpl++; }
    sdu_wr_str(w, replacement);
    sdu_wr_str(w, pos + sdu_strlen(marker));
}

/* ---- resolve unit with plural + half ---- */

static void sdu_resolve_unit(SduWriter *w, int count, const SduUnitForms *uf,
                             const SduDurationLocale *loc, const char *half) {
    const char *base_n = sdu_itoa(count);
    char n_buf[64];
    const char *n_str;
    const char *tmpl;
    SduPluralCategory cat;
    char result_buf[128];
    SduWriter rw;

    /* Apply {n}-style half marker to the number */
    if (half && half[0] && sdu_strstr(half, "{n}")) {
        SduWriter nw;
        sdu_wr_init(&nw, n_buf, sizeof(n_buf));
        sdu_replace_first(&nw, half, "{n}", base_n);
        n_str = n_buf;
    } else {
        n_str = base_n;
    }

    /* Select template */
    tmpl = (const char *)0;
    if (uf->simple) {
        tmpl = uf->simple;
    } else {
        cat = (half && half[0]) ? SDU_OTHER : loc->plural(count);
        if (uf->forms[cat]) {
            tmpl = uf->forms[cat];
        } else if (uf->forms[SDU_OTHER]) {
            tmpl = uf->forms[SDU_OTHER];
        }
    }
    if (!tmpl) return;

    /* Replace {n} with the (possibly half-marked) number */
    sdu_wr_init(&rw, result_buf, sizeof(result_buf));
    sdu_replace_first(&rw, tmpl, "{n}", n_str);
    if (rw.overflow) return;

    /* Apply {0}-style half marker */
    if (half && half[0] && sdu_strstr(half, "{0}")) {
        sdu_replace_first(w, half, "{0}", result_buf);
    } else {
        sdu_wr_str(w, result_buf);
    }
}

/* ---- ISO datetime parsing ---- */

static int sdu_parse_digits(const char *s, int len) {
    int v = 0, i;
    for (i = 0; i < len; i++) {
        char c = s[i];
        if (c < '0' || c > '9') return -1;
        v = v * 10 + (c - '0');
    }
    return v;
}

static bool sdu_is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

static int sdu_days_in_month(int year, int month) {
    if (month == 2) return sdu_is_leap_year(year) ? 29 : 28;
    if (month == 4 || month == 6 || month == 9 || month == 11) return 30;
    return 31;
}

typedef long long sdu_i64;

static sdu_i64 sdu_days_since_epoch(int year, int month, int day) {
    sdu_i64 days = 0;
    int y, m;
    if (year >= 2000) {
        for (y = 2000; y < year; y++) days += sdu_is_leap_year(y) ? 366 : 365;
    } else {
        for (y = year; y < 2000; y++) days -= sdu_is_leap_year(y) ? 366 : 365;
    }
    for (m = 1; m < month; m++) days += sdu_days_in_month(year, m);
    days += day - 1;
    return days;
}

static bool sdu_parse_iso(const char *iso, sdu_i64 *result) {
    int year, month, day, hour, minute, second;
    const char *t_pos;
    const char *time_part;
    const char *p;
    int colon1, rest_start, colon2;
    sdu_i64 d;

    if (!iso || !iso[0]) return false;

    /* Find 'T' */
    t_pos = iso;
    while (*t_pos && *t_pos != 'T') t_pos++;
    if (!*t_pos) return false;

    /* Parse date */
    if ((int)(t_pos - iso) < 10 || iso[4] != '-' || iso[7] != '-') return false;
    year = sdu_parse_digits(iso, 4);
    month = sdu_parse_digits(iso + 5, 2);
    day = sdu_parse_digits(iso + 8, 2);
    if (year < 0 || month < 1 || month > 12 || day < 1 || day > 31) return false;

    /* Parse time - strip timezone */
    time_part = t_pos + 1;

    /* Find first colon */
    p = time_part;
    while (*p && *p != ':') p++;
    if (!*p) return false;
    colon1 = (int)(p - time_part);
    hour = sdu_parse_digits(time_part, colon1);
    if (hour < 0 || hour > 23) return false;

    rest_start = colon1 + 1;
    minute = 0;
    second = 0;

    /* Find second colon or end */
    p = time_part + rest_start;
    colon2 = -1;
    {
        int idx = 0;
        while (p[idx] && p[idx] != ':' && p[idx] != '+' && p[idx] != 'Z') idx++;
        if (p[idx] == ':') {
            colon2 = idx;
            minute = sdu_parse_digits(p, colon2);
            if (minute < 0 || minute > 59) return false;
            /* Parse seconds */
            {
                const char *sec_start = p + colon2 + 1;
                int sec_len = 0;
                while (sec_start[sec_len] && sec_start[sec_len] != '.' && sec_start[sec_len] != '+' && sec_start[sec_len] != 'Z') sec_len++;
                second = sdu_parse_digits(sec_start, sec_len);
                if (second < 0 || second > 59) return false;
            }
        } else {
            minute = sdu_parse_digits(p, idx);
            if (minute < 0 || minute > 59) return false;
        }
    }

    d = sdu_days_since_epoch(year, month, day);
    *result = d * 86400 + (sdu_i64)hour * 3600 + (sdu_i64)minute * 60 + (sdu_i64)second;
    return true;
}

/* ---- round division for month approximation ---- */

static int sdu_round_div(int total_days) {
    sdu_i64 numerator = (sdu_i64)total_days * 200 + 3044;
    return (int)(numerator / 6088);
}

/* ---- resolved locale fields ---- */

typedef struct {
    const SduUnitForms *second, *minute, *hour, *day, *week, *month, *year;
    const char *half;
    const char *delimiter;
    const char *just_now;
    const char *ago;
    const char *in_future;
} SduResolved;

static void sdu_resolve(SduResolved *r, const SduDurationLocale *locale, SduCompactness compactness) {
    const SduCompactnessOverride *ovr;
    r->second = &locale->units.second;
    r->minute = &locale->units.minute;
    r->hour   = &locale->units.hour;
    r->day    = &locale->units.day;
    r->week   = &locale->units.week;
    r->month  = &locale->units.month;
    r->year   = &locale->units.year;
    r->half   = locale->half;
    r->delimiter = locale->delimiter;
    r->just_now  = locale->just_now;
    r->ago       = locale->ago;
    r->in_future = locale->in_future;

    ovr = (const SduCompactnessOverride *)0;
    if (compactness == SDU_SHORT && locale->has_short) ovr = &locale->short_override;
    else if (compactness == SDU_COMPACT && locale->has_compact) ovr = &locale->compact_override;

    if (ovr) {
        if (ovr->has_second) r->second = &ovr->second;
        if (ovr->has_minute) r->minute = &ovr->minute;
        if (ovr->has_hour)   r->hour   = &ovr->hour;
        if (ovr->has_day)    r->day    = &ovr->day;
        if (ovr->has_week)   r->week   = &ovr->week;
        if (ovr->has_month)  r->month  = &ovr->month;
        if (ovr->has_year)   r->year   = &ovr->year;
        if (ovr->has_half)      r->half      = ovr->half;
        if (ovr->has_delimiter) r->delimiter = ovr->delimiter;
        if (ovr->has_ago)       r->ago       = ovr->ago;
        if (ovr->has_in_future) r->in_future = ovr->in_future;
    }
}

/* ---- format duration from seconds (internal) ---- */

static int sdu_format_secs(char *buf, size_t bufsz, const SduDurationLocale *locale,
                           const SduResolved *rl, int total) {
    SduWriter w;
    sdu_wr_init(&w, buf, bufsz);

    /* 0 seconds */
    if (total == 0) {
        sdu_wr_str(&w, rl->just_now);
        return w.overflow ? -1 : 0;
    }

    /* 1-59 seconds */
    if (total < 60) {
        sdu_resolve_unit(&w, total, rl->second, locale, "");
        return w.overflow ? -1 : 0;
    }

    {
        int total_minutes = total / 60;
        int remainder_seconds = total % 60;

        /* 1-4 minutes: minutes + seconds */
        if (total_minutes < 5) {
            sdu_resolve_unit(&w, total_minutes, rl->minute, locale, "");
            if (remainder_seconds > 0) {
                sdu_wr_str(&w, rl->delimiter);
                sdu_resolve_unit(&w, remainder_seconds, rl->second, locale, "");
            }
            return w.overflow ? -1 : 0;
        }

        /* 5-59 minutes */
        if (total_minutes < 60) {
            sdu_resolve_unit(&w, total_minutes, rl->minute, locale, "");
            return w.overflow ? -1 : 0;
        }
    }

    {
        int total_hours = total / 3600;
        int remainder_minutes = (total % 3600) / 60;

        /* 1-5 hours: hours + minutes (with half marker) */
        if (total_hours <= 5) {
            if (remainder_minutes == 30) {
                sdu_resolve_unit(&w, total_hours, rl->hour, locale, rl->half);
            } else {
                sdu_resolve_unit(&w, total_hours, rl->hour, locale, "");
                if (remainder_minutes > 0) {
                    sdu_wr_str(&w, rl->delimiter);
                    sdu_resolve_unit(&w, remainder_minutes, rl->minute, locale, "");
                }
            }
            return w.overflow ? -1 : 0;
        }

        /* 6-23 hours */
        if (total_hours < 24) {
            sdu_resolve_unit(&w, total_hours, rl->hour, locale, "");
            return w.overflow ? -1 : 0;
        }
    }

    {
        int total_days = total / 86400;
        int remainder_hours = (total % 86400) / 3600;

        /* 1-2 days: days + hours (with half marker) */
        if (total_days <= 2) {
            if (remainder_hours == 12) {
                sdu_resolve_unit(&w, total_days, rl->day, locale, rl->half);
            } else {
                sdu_resolve_unit(&w, total_days, rl->day, locale, "");
                if (remainder_hours > 0) {
                    sdu_wr_str(&w, rl->delimiter);
                    sdu_resolve_unit(&w, remainder_hours, rl->hour, locale, "");
                }
            }
            return w.overflow ? -1 : 0;
        }

        /* 3-6 days */
        if (total_days < 7) {
            sdu_resolve_unit(&w, total_days, rl->day, locale, "");
            return w.overflow ? -1 : 0;
        }

        /* 1-4 weeks (up to 29 days) */
        if (total_days < 30) {
            int total_weeks = total_days / 7;
            int remainder_days = total_days % 7;
            sdu_resolve_unit(&w, total_weeks, rl->week, locale, "");
            if (remainder_days > 0) {
                sdu_wr_str(&w, rl->delimiter);
                sdu_resolve_unit(&w, remainder_days, rl->day, locale, "");
            }
            return w.overflow ? -1 : 0;
        }

        /* Approximate months */
        {
            int total_months = sdu_round_div(total_days);
            if (total_months < 12) {
                if (total_months == 0) total_months = 1;
                sdu_resolve_unit(&w, total_months, rl->month, locale, "");
                return w.overflow ? -1 : 0;
            }

            /* Years + months */
            {
                int total_years = total_months / 12;
                int remainder_months = total_months % 12;
                sdu_resolve_unit(&w, total_years, rl->year, locale, "");
                if (remainder_months > 0) {
                    sdu_wr_str(&w, rl->delimiter);
                    sdu_resolve_unit(&w, remainder_months, rl->month, locale, "");
                }
                return w.overflow ? -1 : 0;
            }
        }
    }
}

/* ---- public API ---- */

int sdu_format_duration_secs(char *buf, size_t bufsz, const SduDurationLocale *locale,
                             SduCompactness compactness, int seconds) {
    SduResolved rl;
    if (!buf || bufsz == 0 || !locale || seconds < 0) return -1;
    buf[0] = '\0';
    sdu_resolve(&rl, locale, compactness);
    return sdu_format_secs(buf, bufsz, locale, &rl, seconds);
}

int sdu_format_duration_iso(char *buf, size_t bufsz, const SduDurationLocale *locale,
                            SduCompactness compactness, const char *start, const char *end) {
    sdu_i64 s, e, diff;
    SduResolved rl;

    if (!buf || bufsz == 0 || !locale) return -1;
    buf[0] = '\0';

    if (!sdu_parse_iso(start, &s)) return -1;
    if (!sdu_parse_iso(end, &e)) return -1;

    diff = e - s;
    if (diff < 0) diff = -diff;

    sdu_resolve(&rl, locale, compactness);
    return sdu_format_secs(buf, bufsz, locale, &rl, (int)diff);
}

int sdu_format_since(char *buf, size_t bufsz, const SduDurationLocale *locale,
                     SduCompactness compactness, const char *start, const char *as_of) {
    sdu_i64 s, a, diff;
    SduResolved rl;
    char dur_buf[256];
    SduWriter w;

    if (!buf || bufsz == 0 || !locale) return -1;
    buf[0] = '\0';

    if (!sdu_parse_iso(start, &s)) return -1;
    if (!sdu_parse_iso(as_of, &a)) return -1;

    diff = a - s;
    if (diff < 0) return -1;

    sdu_resolve(&rl, locale, compactness);

    if (diff == 0) {
        sdu_wr_init(&w, buf, bufsz);
        sdu_wr_str(&w, rl.just_now);
        return w.overflow ? -1 : 0;
    }

    if (sdu_format_secs(dur_buf, sizeof(dur_buf), locale, &rl, (int)diff) != 0) return -1;

    sdu_wr_init(&w, buf, bufsz);
    sdu_replace_first(&w, rl.ago, "{0}", dur_buf);
    return w.overflow ? -1 : 0;
}

int sdu_format_until(char *buf, size_t bufsz, const SduDurationLocale *locale,
                     SduCompactness compactness, const char *target, const char *as_of) {
    sdu_i64 t, a, diff;
    SduResolved rl;
    char dur_buf[256];
    SduWriter w;

    if (!buf || bufsz == 0 || !locale) return -1;
    buf[0] = '\0';

    if (!sdu_parse_iso(target, &t)) return -1;
    if (!sdu_parse_iso(as_of, &a)) return -1;

    diff = t - a;
    if (diff < 0) return -1;

    sdu_resolve(&rl, locale, compactness);

    if (diff == 0) {
        sdu_wr_init(&w, buf, bufsz);
        sdu_wr_str(&w, rl.just_now);
        return w.overflow ? -1 : 0;
    }

    if (sdu_format_secs(dur_buf, sizeof(dur_buf), locale, &rl, (int)diff) != 0) return -1;

    sdu_wr_init(&w, buf, bufsz);
    sdu_replace_first(&w, rl.in_future, "{0}", dur_buf);
    return w.overflow ? -1 : 0;
}
